import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第四册：流利英语 · Lesson 20 Snake poison","description":"学习 过去分词作后置定语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 20 Snake poison","description":"学习 过去分词作后置定语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 过去分词作后置定语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 19 The stuff of dreams","link":"/life/english/new-concept/book-4/unit-03/lesson-019"},"next":{"text":"第四册：流利英语 · Lesson 21 William S. Hart and the early 'Western' film","link":"/life/english/new-concept/book-4/unit-03/lesson-021"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 19 The stuff of dreams","link":"/life/english/new-concept/book-4/unit-03/lesson-019"},"next":{"text":"第四册：流利英语 · Lesson 21 William S. Hart and the early 'Western' film","link":"/life/english/new-concept/book-4/unit-03/lesson-021"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-03/lesson-020.md","filePath":"life/english/new-concept/book-4/unit-03/lesson-020.md"}`),l={name:"life/english/new-concept/book-4/unit-03/lesson-020.md"};function s(i,e,r,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-20-snake-poison" tabindex="-1">第四册：流利英语 · Lesson 20 Snake poison <a class="header-anchor" href="#第四册-流利英语-·-lesson-20-snake-poison" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 20 Snake poison&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从蛇毒这一历史科普主题训练分类阅读：不同物质、不同作用与不同研究条件不能混成一个结论。练习用定语和分词缩短说明而保留必要范围。涉及人体影响的内容只作为阅读与证据表达训练，不从文学化或旧科普描写推出具体处置方法。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>venom</td><td>/ˈvenəm/</td><td>n.</td><td>毒液</td><td>snake venom</td></tr><tr><td>substance</td><td>/ˈsʌbstəns/</td><td>n.</td><td>物质</td><td>an active substance</td></tr><tr><td>component</td><td>/kəmˈpəʊnənt/</td><td>n.</td><td>成分</td><td>a major component</td></tr><tr><td>sample</td><td>/ˈsɑːmpəl/</td><td>n.</td><td>样本</td><td>a labelled sample</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>consist of — 由若干部分组成</li><li>under controlled conditions — 在受控条件下</li></ul><h2 id="语法讲解-过去分词作后置定语" tabindex="-1">语法讲解：过去分词作后置定语 <a class="header-anchor" href="#语法讲解-过去分词作后置定语" aria-label="Permalink to &quot;语法讲解：过去分词作后置定语&quot;">​</a></h2><p>名词 + 过去分词短语通常可展开为被动关系从句：samples collected yesterday 等于 samples that were collected yesterday。过去分词不必总表示过去时间，关键是与名词的被动关系；the methods used today 也可指现在。现在分词通常表达主动或进行关系。写作时要清楚谁执行动作，避免把 substances producing an effect 与 substances produced in a laboratory 混淆。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The samples collected on Tuesday were analysed separately.</p></blockquote><p>周二采集的样本被分别分析。</p><p>collected on Tuesday 后置修饰 samples，相当于 that were collected；were analysed 是全句谓语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不要把 collected 当成全句唯一谓语而漏掉 were analysed；该短语只限定样本。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>把 The samples collected on Tuesday 作为一组读完，再重读 were analysed；通过停顿区分定语与谓语。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The samples collected at different sites were kept separate. Each group was given a clear label. Results from one group cannot automatically be applied to another.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句写实验样本管理说明，包含采集、分组和结论范围。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>用分词定语说明来源，用末句避免跨组过度概括；不涉及危险操作或医疗处置。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>展开 samples collected on Tuesday 中的分词定语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> samples that were collected on Tuesday</p><p><strong>解析：</strong> 过去分词定语对应被动关系从句。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例中全句谓语是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were analysed</p><p><strong>解析：</strong> collected 属于主语内部的修饰语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>选择：“实验室生产的物质”是 substances producing / produced in a laboratory？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> substances produced in a laboratory</p><p><strong>解析：</strong> 物质是被生产的，使用过去分词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去分词作后置定语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-019">上一课</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-03/lesson-021">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(l,[["render",s]]);export{u as __pageData,b as default};
